const item = $input.first()?.json || {};
const rawMessage = String(item.chatInput || item.message || item.text || '').trim();
const sessionId = String(item.sessionId || 'session_' + Date.now());
const startTime = Date.now();

if (rawMessage.length === 0) {
  return [{
    json: {
      passed: false,
      reason: 'EMPTY_INPUT',
      session_id: sessionId,
      question: '',
      intent: 'UNKNOWN',
      confidence: 0.0,
      status: 'GUARD_REJECTED',
      response_text: 'Lütfen bir soru veya mesaj yazınız.',
      start_time: startTime,
      needs_fresh_data: false,
      entities: {},
      injection_suspected: false
    }
  }];
}

if (rawMessage.length > 2000) {
  return [{
    json: {
      passed: false,
      reason: 'EXCESSIVE_LENGTH',
      session_id: sessionId,
      question: rawMessage.substring(0, 2000),
      intent: 'UNKNOWN',
      confidence: 0.0,
      status: 'GUARD_REJECTED',
      response_text: 'Mesajınız çok uzun. Lütfen sorunuzu 2000 karakterden kısa olacak şekilde iletiniz.',
      start_time: startTime,
      needs_fresh_data: false,
      entities: {},
      injection_suspected: false
    }
  }];
}

const injectionPatterns = [
  /ignore (all )?previous instructions/i,
  /system prompt/i,
  /jailbreak/i,
  /dan mode/i,
  /drop table/i,
  /eval\(/i,
  /exec\(/i
];
const injectionSuspected = injectionPatterns.some(p => p.test(rawMessage));

return [{
  json: {
    passed: true,
    session_id: sessionId,
    question: rawMessage,
    start_time: startTime,
    injection_suspected: injectionSuspected
  }
}];

