const guard = $('Input Normalization & Guard').first().json;

if (!guard.passed) {
  return [{
    json: {
      session_id: guard.session_id,
      question: guard.question,
      intent: 'UNKNOWN',
      confidence: 0.0,
      status: 'GUARD_REJECTED',
      response_text: guard.response_text,
      latency_ms: Date.now() - guard.start_time,
      metadata: { rejection_reason: guard.reason }
    }
  }];
}

const httpResponse = $input.first().json;
const rawContent = httpResponse.message?.content || httpResponse.response || '';

let parsed = null;
try {
  let clean = rawContent.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
  clean = clean.replace(/^```json\s*/i, '').replace(/^```\s*/, '').replace(/```\s*$/, '').trim();
  const firstB = clean.indexOf('{');
  const lastB = clean.lastIndexOf('}');
  if (firstB !== -1 && lastB !== -1 && lastB > firstB) {
    clean = clean.substring(firstB, lastB + 1);
  }
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = {
    intent: 'UNKNOWN',
    confidence: 0.0,
    normalized_question: guard.question,
    entities: {},
    needs_fresh_data: false,
    reason: 'JSON parse error: ' + e.message
  };
}

const validIntents = ['HR_POLICY', 'ATTENDANCE_SQL', 'PROJECT_MAIL', 'HYBRID', 'UNKNOWN'];
let intent = validIntents.includes(parsed.intent) ? parsed.intent : 'UNKNOWN';
let confidence = typeof parsed.confidence === 'number' ? Math.max(0, Math.min(1, parsed.confidence)) : 0.5;
let status = 'SUCCESS';
let responseText = '';

if (confidence < 0.75 && intent !== 'UNKNOWN') {
  status = 'LOW_CONFIDENCE';
  intent = 'UNKNOWN';
  responseText = `Sorunuz tam anlaşılamadı (Güven: %${Math.round(confidence * 100)}). Lütfen şirket politikaları, devam durumu veya proje yazışmalarıyla ilgili daha net bir soru belirtiniz.`;
} else {
  switch (intent) {
    case 'HR_POLICY':
      responseText = 'HR route selected (İK RAG ve CAG modülleri sonraki aşamada bağlanacak).';
      break;
    case 'ATTENDANCE_SQL':
      responseText = 'ATTENDANCE_SQL route selected (Devam takip SQL modülü sonraki aşamada bağlanacak).';
      break;
    case 'PROJECT_MAIL':
      responseText = 'PROJECT_MAIL route selected (Proje e-posta aracı sonraki aşamada bağlanacak).';
      break;
    case 'HYBRID':
      responseText = 'HYBRID route selected (Hibrit yönetim modülü sonraki aşamada bağlanacak).';
      break;
    case 'UNKNOWN':
    default:
      responseText = 'UNKNOWN route selected (Sorunuz şirket politikaları, devam durumu veya proje yazışmaları kapsamı dışındadır).';
      break;
  }
}

const latencyMs = Date.now() - guard.start_time;

return [{
  json: {
    session_id: guard.session_id,
    question: guard.question,
    intent,
    confidence,
    status,
    normalized_question: parsed.normalized_question || guard.question,
    entities: parsed.entities || {},
    needs_fresh_data: Boolean(parsed.needs_fresh_data),
    reason: parsed.reason || '',
    response_text: responseText,
    latency_ms: latencyMs,
    metadata: {
      entities: parsed.entities || {},
      needs_fresh_data: Boolean(parsed.needs_fresh_data),
      reason: parsed.reason || '',
      injection_suspected: guard.injection_suspected || false,
      model: 'qwen3.5:9b'
    }
  }
}];
